// Парсинг входящего сообщения от Telegram
const message = $input.item.json.message.text;

// Регулярные выражения для извлечения данных
const patterns = {
  platform: /Биржа:\s*(.+)/i,
  link: /Ссылка:\s*(.+)/i,
  title: /Заголовок:\s*(.+)/i,
  description: /Описание:\s*([\s\S]+?)(?=Бюджет:|$)/i,
  budget: /Бюджет:\s*(.+)/i,
  deadline: /Дедлайн:\s*(.+)/i
};

// Извлечение данных
const extractedData = {
  platform: (message.match(patterns.platform) || ['', 'Не указано'])[1].trim(),
  link: (message.match(patterns.link) || ['', ''])[1].trim(),
  title: (message.match(patterns.title) || ['', 'Без названия'])[1].trim(),
  description: (message.match(patterns.description) || ['', message])[1].trim(),
  budget: (message.match(patterns.budget) || ['', 'Не указан'])[1].trim(),
  deadline: (message.match(patterns.deadline) || ['', 'Не указан'])[1].trim(),
  chatId: $input.item.json.message.chat.id,
  messageId: $input.item.json.message.message_id,
  originalMessage: message
};

return {
  json: extractedData
};

